import { expect, expectTypeOf, assertType } from "./test/expect-shim.mjs";
import { zip } from "./src/array/zip.js";
{
{
{
expect(zip([1, 2, 3])).toEqual([[1], [2], [3]]);
        expect(zip([1, 2, 3], ['a', 'b', 'c'])).toEqual([
            [1, 'a'],
            [2, 'b'],
            [3, 'c'],
        ]);
        expect(zip([1, 2, 3], ['a', 'b'])).toEqual([
            [1, 'a'],
            [2, 'b'],
            [3, undefined],
        ]);
        expect(zip([1, 2, 3], ['a', 'b', 'c'], [true, true, false])).toEqual([
            [1, 'a', true],
            [2, 'b', true],
            [3, 'c', false],
        ]);
        expect(zip([1], ['a'], [true], [null])).toEqual([[1, 'a', true, null]]);
}
}
}

